// items  = baris dari sheet 'Ambil Catatan' (referensi agar tidak mengulang)
// $node  = output node lain pada eksekusi ini
const catatan = items
  .map((r) => String(r.catatan || r.judul || '').trim())
  .filter(Boolean);
const setelan = ($node['Setelan'] || [{}])[0] || {};
const nomor = catatan.length + 1;
const judul = 'Tugas #' + nomor;

return [{
  agen: setelan.agen || 'agen-1',
  judul,
  prompt: [
    'Kerjakan ' + judul + '.',
    'Gaya: ' + (setelan.gaya || 'ringkas'),
    'Jangan ulangi catatan yang sudah ada: ' + (catatan.length ? catatan.join('; ') : '(belum ada)'),
    'Balas JSON: {"judul": "...", "hasil": "..."}'
  ].join('\n'),
  gaya: setelan.gaya,
  maks_putaran: setelan.maks_putaran,
  diminta: new Date().toISOString()
}];

// http node bisa membalas { error, status, body } saat gagal (allowNon2xx)
const raw = items[0] || {};
const data = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const tugas = ($node['Susun Tugas'] || [{}])[0] || {};
const task_id = data.task_id !== undefined ? data.task_id : (data.id !== undefined ? data.id : null);

$vars.coba = ($vars.coba || 0) + 1;

return [{
  task_id,
  status: data.status || (task_id ? 'terkirim' : 'menunggu'),
  error: raw.error || null,
  percobaan: $vars.coba,
  judul: data.judul || tugas.judul || null
}];

$vars.cek = ($vars.cek || 0) + 1;

const hasil = items.filter((i) => i && i.status !== 'diproses' && (i.hasil || i.ide || i.output));
if (!hasil.length) {
  return [{ menunggu: true, jumlah: 0, putaran: $vars.cek }];
}
return hasil.map((h) => Object.assign({ menunggu: false, putaran: $vars.cek }, h));

const out = [];
for (const it of items) {
  if (!it || it.menunggu) continue;
  const isi = it.hasil || it.ide || it.output || '';
  if (!isi) continue;
  out.push({
    dibuat: new Date().toISOString(),
    task_id: it.task_id !== undefined ? it.task_id : (it.id || ''),
    agen: it.agen || '',
    judul: it.judul || '',
    hasil: String(isi).replace(/\s+/g, ' ').trim().slice(0, 2000)
  });
}
return out;
